def clean(df):
    d = df.copy()
    # drop exact duplicate rows
    d = d.drop_duplicates()
    # normalize island labels (strip spaces, fix case variants to allowed values)
    allowed_islands = {'biscoe': 'Biscoe', 'dream': 'Dream', 'torgersen': 'Torgersen'}
    d['island'] = d['island'].astype('object').where(d['island'].notna(), None)
    d['island'] = d['island'].map(
        lambda v: allowed_islands.get(str(v).strip().lower(), str(v).strip()) if v is not None and str(v) != 'nan' else None
    )
    # normalize species labels similarly
    allowed_species = {'adelie': 'Adelie', 'chinstrap': 'Chinstrap', 'gentoo': 'Gentoo'}
    d['species'] = d['species'].map(
        lambda v: allowed_species.get(str(v).strip().lower(), str(v).strip()) if v is not None and str(v) != 'nan' else None
    )
    # body_mass_g written as text (with commas) -> numeric
    d['body_mass_g'] = pd.to_numeric(
        d['body_mass_g'].astype(str).str.replace(',', '', regex=False).str.strip(), errors='coerce'
    )
    # out-of-range body mass -> treat as missing (row itself is kept; it does not affect the count)
    d.loc[(d['body_mass_g'] < 2500) | (d['body_mass_g'] > 6500), 'body_mass_g'] = pd.NA
    # numeric columns that arrived as text
    for c in ['flipper_length_mm', 'year']:
        d[c] = pd.to_numeric(d[c].astype(str).str.replace(',', '', regex=False).str.strip(), errors='coerce')
    return d


def answer(df):
    d = clean(df)
    d = d.dropna(subset=['island'])
    counts = d.groupby('island').size()
    return {str(k): int(v) for k, v in counts.items()}
